    for c in range(c_min + 1, c_max):
        solution[r][c] = 0

frames = [
    (1, 8, 12, 11, 18, "R->L"),   # H=3, W=6
    (6, 14, 19, 15, 20, "L->R"),  # H=4, W=4
    (3, 18, 21, 4, 12, "L->R"),   # H=2, W=7
]

for color, r_min, r_max, c_min, c_max, direction in frames:
    r_start, r_end = r_min + 1, r_max - 1
    c_start, c_end = c_min + 1, c_max - 1
    H = r_end - r_start + 1
    W = c_end - c_start + 1

    print(f"Frame {color}: interior {H}x{W}, dir={direction}")

    if direction == "R->L":
        pattern = zigzag_R_to_L(H, W)
    else:
        pattern = zigzag_L_to_R(H, W)

    for i, filled_cols in pattern.items():
        r = r_start + i
        for c in filled_cols:
            solution[r][c_start + c] = color
        row_str = "".join("#" if solution[r][c] == color else "." for c in range(c_start, c_end + 1))
        print(f"  i={i}: fill={filled_cols} -> {row_str}")

print("\nFinal solution:")
print(json.dumps(solution))
